turn itemObject\n"},["scripts/items/choco-scroll.lua"]={["Path"]="scripts/items/choco-scroll.lua",["SHA256"]="b11fa1b8cce7c1542479de19d93179a399010c721b18417c5a6b101695536bc0",["Text"]="-----------------------------------\n-- ID: 5917\n-- Item: Choco-scroll\n-- Food Effect: 3 Min, All Races\n-----------------------------------\n-- Mind 1\n-- Base speed 10% or +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MND, 1)\n    effect:addMod(xi.mod.MOVE_SPEED_QUICKENING, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/chocobiscuit.lua"]={["Path"]="scripts/items/chocobiscuit.lua",["SHA256"]="bf2bd81d39c6de312badb31b5c2af17c1e6cd5f9726899774b367cf41046d33d",["Text"]="-----------------------------------\n-- ID: 5934\n-- Item: Chocobiscuit\n-- Food Effect: 3Min, All Races\n-----------------------------------\n-- Magic Regen While Healing 3\n-- Charisma 3\n-- Evasion 2\n-- Aquan Killer 10\n-- Silence Resist 10\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MPHEAL, 3)\n    effect:addMod(xi.mod.CHR, 3)\n    effect:addMod(xi.mod.EVA, 2)\n    effect:addMod(xi.mod.AQUAN_KILLER, 10)\n    effect:addMod(xi.mod.SILENCERES, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/chocobo_chair.lua"]={["Path"]="scripts/items/chocobo_chair.lua",["SHA256"]="101f25b347e9da1878162afb2952d2ac2acf4f3e6ac6bb05888664cade9f26b5",["Text"]="-----------------------------------\n-- ID: 6411\n-- Item: Chocobo Chair\n-- Item Effect: Grant Chocobo chair key item\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nlocal keyItemId = xi.keyItem.CHOCOBO_CHAIR\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasKeyItem(keyItemId) then\n        return xi.msg.basic.ALREADY_HAVE_KEY_ITEM, 0, keyItemId\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addKeyItem(keyItemId)\n    target:messageBasic(xi.msg.basic.OBTAINED_KEY_ITEM, xi.item.CHOCOBO_CHAIR, keyItemId)\nend\n\nreturn itemObject\n"},["scripts/items/chocobo_pullus_torque.lua"]={["Path"]="scripts/items/chocobo_pullus_torque.lua",["SHA256"]="1df08cdbd888b185f5a33968dc32decd9b5fd4885878f936d54eb4696f7fc610",["Text"]="-----------------------------------\n-- ID: 16273\n-- Chocobo Pullus Torque\n-- Enchantment: 60Min, Costume - Mandragora\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 1997, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/chocobo_shield_+1.lua"]={["Path"]="scripts/items/chocobo_shield_+1.lua",["SHA256"]="54ff0f215e039647915378dadb3f30dfe32c29666803c553caef363d13b8c80a",["Text"]="-----------------------------------\n-- ID: 10812\n-- Item: Chocobo Shield +1\n-- Dispense: Sakura Biscuit\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.SAKURA_BISCUIT, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/chocobo_shirt.lua"]={["Path"]="scripts/items/chocobo_shirt.lua",["SHA256"]="ae1103bf06f8564a47ca4adf724143f5c726005856cb489382ce6a80bd7f0d63",["Text"]="-----------------------------------\n-- ID: 10293\n-- Chocobo Shirt\n-- Dispense: Crystals\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    -- Crystal Item IDs:\n    -- 4096 Fire\n    -- 4097 Ice\n    -- 4098 Wind\n    -- 4099 Earth\n    -- 4100 Thunder\n    -- 4101 Water\n    -- 4102 Light\n    -- 4103 Dark\n    local itemID = 4095 + VanadielDayElement()\n    npcUtil.giveItem(target, { { itemID, math.randomInt(2, 12) } })\nend\n\nreturn itemObject\n"},["scripts/items/chocobo_whistle.lua"]={["Path"]="scripts/items/chocobo_whistle.lua",["SHA256"]="d44a1904115bf8ba7dc1887080da0cea7b132ebed28dab5b76c9c8bbdcd48ac8",["Text"]="-----------------------------------\n-- ID: 15533\n-- Item: Chocobo Whistle\n-----------------------------------\nrequire('scripts/globals/hobbies/chocobo_raising/whistle')\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.MOUNT) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    elseif\n        target:getMainLvl() < 20 or\n        not target:hasKeyItem(xi.keyItem.CHOCOBO_LICENSE) or\n        target:hasEnmity()\n    then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE -- TODO: Verify/correct message, order of message priority.\n    end\n\n    -- TODO: The message for a whistle with no chocobo registered.\n    if not target:getFieldChocobo() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local ride = xi.chocoboRaising.whistle.ride(target)\n\n    target:addStatusEffect(xi.effect.MOUNTED,\n    {\n        power    = xi.mount.CHOCOBO,\n        duration = ride.seconds,\n        origin   = user,\n        subPower = xi.chocoboRaising.personalChocoboFlag,\n        silent   = true,\n    })\nend\n\nreturn itemObject\n"},["scripts/items/chocolate_cake.lua"]={["Path"]="scripts/items/chocolate_cake.lua",["SHA256"]="6e03df026a7b1c7adb1a9e49e7efe4c947588cf34bdfc87264258cef8086001b",["Text"]="-----------------------------------\n-- ID: 5633\n-- Item: Chocolate Cake\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- TODO: Group Effect\n-- MP +3% (cap 90)\n-- HP Recovered while healing +1\n-- MP Recovered while healing +6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 3)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 90)\n    effect:addMod(xi.mod.HPHEAL, 1)\n    effect:addMod(xi.mod.MPHEAL, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/chocolate_crepe.lua"]={["Path"]="scripts/items/chocolate_crepe.lua",["SHA256"]="21bf7ea92c6f0cb8ce7a70c4ba276d025533c6bd5f164b04746d5c52ddb20b0f",["Text"]="-----------------------------------\n-- ID: 5775\n-- Item: Chocol