xi.mod.HPHEAL, 5)\n    effect:addMod(xi.mod.LIZARD_KILLER, 5)\n    effect:addMod(xi.mod.PETRIFYRES, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/chunk_of_hobgoblin_chocolate.lua"]={["Path"]="scripts/items/chunk_of_hobgoblin_chocolate.lua",["SHA256"]="23ab59be9e8e0065c80a3bfe2b7a6e395e1a3dc8678944e8c043c4d3cd615574",["Text"]="-----------------------------------\n-- ID: 4324\n-- Item: chunk_of_hobgoblin_chocolate\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Health Regen While Healing 7\n-- Lizard Killer 12\n-- Petrify Resist 12\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.HPHEAL, 7)\n    effect:addMod(xi.mod.LIZARD_KILLER, 12)\n    effect:addMod(xi.mod.PETRIFYRES, 12)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/chunk_of_homemade_cheese.lua"]={["Path"]="scripts/items/chunk_of_homemade_cheese.lua",["SHA256"]="6bf51b2adf82672cfc417f8e97e3adf5acab9a738c82adeaac54e7c3e7a64458",["Text"]="-----------------------------------\n-- ID: 5225\n-- Item: chunk_of_homemade_cheese\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health 10\n-- Accuracy +12% (cap 80)\n-- Attack +10% (cap 40)\n-- Ranged Accuracy +12% (cap 80)\n-- Ranged Attack +10% (cap 40)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.FOOD_ACCP, 12)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_ATTP, 10)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 40)\n    effect:addMod(xi.mod.FOOD_RACCP, 12)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_RATTP, 10)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 40)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/chunk_of_hydra_meat.lua"]={["Path"]="scripts/items/chunk_of_hydra_meat.lua",["SHA256"]="7cc1fb2049c9089da910713109b14aaf1d3f75097b0d88264ce8405144dae2d4",["Text"]="-----------------------------------\n-- ID: 5564\n-- Item: Chunk of Hydra Meat\n-- Effect: 5 Minutes, food effect, Galka Only\n-----------------------------------\n-- HP 10\n-- MP -10\n-- Strength +6\n-- Intelligence -8\n-- Demon Killer 10\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_MEAT)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.FOOD_MP, -10)\n    effect:addMod(xi.mod.STR, 6)\n    effect:addMod(xi.mod.INT, -8)\n    effect:addMod(xi.mod.DEMON_KILLER, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/chunk_of_orobon_meat.lua"]={["Path"]="scripts/items/chunk_of_orobon_meat.lua",["SHA256"]="37747000bfe3e3319e2487a6e2bb5b24eb6f83567c034fa99cdfc9a9eeeb876f",["Text"]="-----------------------------------\n-- ID: 5563\n-- Item: Chunk of Orobon Meat\n-- Effect: 5 Minutes, food effect, Galka Only\n-----------------------------------\n-- HP 10\n-- MP -10\n-- Strength +6\n-- Intelligence -8\n-- Demon Killer 10\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_MEAT)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.FOOD_MP, -10)\n    effect:addMod(xi.mod.STR, 6)\n    effect:addMod(xi.mod.INT, -8)\n    effect:addMod(xi.mod.DEMON_KILLER, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/chunk_of_shumeyo_salt.lua"]={["Path"]="scripts/items/chunk_of_shumeyo_salt.lua",["SHA256"]="12a61a7b605e6e45bb4ae1841273624e59fb18b40ee468c1df8dc5dffb93293f",["Text"]="-----------------------------------\n-- ID: 5267\n-- Item: Chunk Of Shu'Meyo Salt\n-- Effect: Adds 20 seconds to the Snoll Tzar fight\n-----------------------------------\nlocal ID = zones[xi.zone.BEARCLAW_PINNACLE]\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local msg     = 0\n    local offset  = target:getBattlefield():getArea() - 1\n    local snollID = ID.mob.SNOLL_TZAR_OFFSET + offset\n\n    if target:getID() ~= snollID then\n        msg = xi.msg.basic.ITEM_UNABLE_TO_USE\n    elseif target:checkDistance(caster) > 10 then\n        msg = xi.msg.basic.TOO_FAR_AWAY\n    end\n\n    return msg\nend\n\nitemObject.onItemUse = function(target, player)\n    local currentTime = GetSystemTime()\n    local changeTime = target:getLocalVar('changeTime')\n    local saltTime = target:getLocalVar('saltTime')\n\n    -- Delay next form change by 20 seconds\n    target:setLocalVar('changeTime', changeTime + 20)\n\n    if saltTime < currentTime then\n        target:messageText(target, ID.text.BEGINS_TO_MELT)\n        target:setLocalVar('saltTime', currentTime + 20)\n        target:setLocalVar('nextSteam', currentTime + math.randomInt(7, 10))\n\n    -- Extend existing salt duration by 20 seconds\n    else\n        target:setLocalVar('saltTime', saltTime + 20)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/chunk_of_smelling_salts.lua"]={["Path"]="scripts/items/chunk_of_smelling_salts.lua",["SHA256"]="33a55eac3d3dc6938d1bc35b30ee1ffe0a6694a6238d994de4f08bdccf8ba5b2",["Text"]="-----------------------------------\n-- ID: 5320\n-- Item: Chunk of Smelling Salts\n-- Item Effect: Recover Pets from Sleep\n-- Duration: 180 Secs Medicated\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local pet = target:getPet()\n\n    if not pet then\n        return xi.msg.basic.REQUIRES_A_PET\n    elseif pet:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:addStatusEffect(xi.effect.MEDICINE, { duration = 180, origin = user, subType = 5320 }) then\n        local pet = target:getPet()\n        if not pet then\n            return\n        end\n\n        -- TODO: Verify targeting and messages are correct\n        target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.MEDICINE)\n        pet:delStatusEffect(xi.effect.SLEEP_I)\n        pet:delStatusEffect(xi.effect.SLEEP_II)\n        pet:delStatusEffect(xi.effect.LULLABY)\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/chunk_of_sweet_lizard.lua"]={["Path"]="scripts/items/chunk_of_sweet_lizard.lua",["SHA256"]="3fdb3e5d212277d64e297c09a2e1a445db6556d558a864b850253e938341f384",["Text"]="-----------------------------------\n-- ID: 5738\n-- Item: chunk_of_sweet_lizard\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- HP 5\n-- MP 5\n-- Dexterity 1\n-- hHP +2\n-- hMP +2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 5)\n    effect:addMod(xi.mod.FOOD_MP, 5)\n    effect:addMod(xi.mod.DEX, 1)\n    effect:addMod(xi.mod.HPHEAL, 2)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cinna-cookie.lua"]={["Path"]="scripts/items/cinna-cookie.lua",["SHA256"]="37d8e1291b02b1f607c6c973d418466e302273ff9809db9fd8cddbc85bb9197b",["Text"]="-----------------------------------\n-- ID: 4397\n-- Item: cinna-cookie\n-- Food Effect: 3Min, All Races\n-----------------------------------\n-- Magic Regen While Healing 4\n-- Vermin Killer 10\n-- Poison Resist 10\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MPHEAL, 4)\n    effect:addMod(xi.mod.VERMIN_KILLER, 10)\n    effect:addMod(xi.mod.POISONRES, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cirrocumulus_cell.lua"]={["Path"]="scripts/items/cirrocumulus_cell.lua",["SHA256"]="df0b9736c9fe54c7da6fc7f32c3c53d0889729e585c1155ea0f85b6c23a7afff",["Text"]="-----------------------------------\n-- Cirrocumulus Cell\n-- ID 5370\n-- Unlocks back and waist equipment\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local encumbrance = target:getStatusEffect(xi.effect.ENCUMBRANCE_I)\n    if encumbrance then\n        local power = encumbrance:getPower()\n        if bit.band(power, 0x8400) > 0 then\n            return 0\n        end\n    end\n\n    return -1\nend\n\nitemObject.onItemUse = function(target, user)\n    local encumbrance = target:getStatusEffect(xi.effect.ENCUMBRANCE_I)\n    if not encumbrance then\n        return\n    end\n\n    local power = encumbrance:getPower()\n    local newpower = bit.band(power, bit.bnot(0x8400))\n    target:delStatusEffectSilent(xi.effect.ENCUMBRANCE_I)\n    if newpower > 0 then\n        target:addStatusEffect(xi.effect.ENCUMBRANCE_I, { power = newpower, origin = user })\n    end\n\n    target:messageText(target, zones[target:getZoneID()].text.CELL_OFFSET + 5)\nend\n\nreturn itemObject\n"},["scripts/items/clear_drop.lua"]={["Path"]="scripts/items/clear_drop.lua",["SHA256"]="87265dbfc028b3d5129c2fdc479b597685eea4eea702f269aece8599cb28dd47",["Text"]="-----------------------------------\n--  ID: 4259\n--  Item: Clear Drop\n--  Intelligence 5\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.INT_BOOST, { power = 5, duration = 600, origin = user })\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/clump_of_batagreens.lua"]={["Path"]="scripts/items/clump_of_batagreens.lua",["SHA256"]="fde6d0af46d0dac6249f471dd017e53e7b05e0daba4d5752d5ceb7eefcb8e7b9",["Text"]="-----------------------------------\n-- ID: 4367\n-- Item: clump_of_batagreens\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility 2\n-- Vitality -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 2)\n    effect:addMod(xi.mod.VIT, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/clump_of_beaugreens.lua"]={["Path"]="scripts/items/clump_of_beaugreens.lua",["SHA256"]="8a349877f74764330b73b5cb3b1d4a507a2a1087521a9ebd414a4fc10ca1197d",["Text"]="-----------------------------------\n-- ID: 4571\n-- Item: clump_of_beaugreens\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility 2\n-- Vitality -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 2)\n    effect:addMod(xi.mod.VIT, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/clump_of_shungiku.lua"]={["Path"]="scripts/items/clump_of_shungiku.lua",["SHA256"]="29520f11146074bfe7731bc7064bfd403827e258909d77860e53621136c35462",["Text"]="-----------------------------------\n-- ID: 5236\n-- Item: Clump of Shungiku\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility +1\n-- Vitality -1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.VIT, -1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cluster_of_bitter_memories.lua"]={["Path"]="scripts/items/cluster_of_bitter_memories.lua",["SHA256"]="0bf9d671db2de524c6d9db09c5b7db82ff06bc757f85b23587996fe081cbd54c",["Text"]="-----------------------------------\n-- ID: 5287\n-- Cluster of bitter memories\n-- Turn into a stack of bitter memories\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BITTER_MEMORY, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/cluster_of_burning_memories.lua"]={["Path"]="scripts/items/cluster_of_burning_memories.lua",["SHA256"]="0c793892d4f6c813dfbef98388c1e0b48ac1ce037e710026fab209305ce2489d",["Text"]="-----------------------------------\n-- ID: 5286\n-- Cluster of burning memories\n-- Turn into a stack of burning memories\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BURNING_MEMORY, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/cluster_of_fleeting_memories.lua"]={["Path"]="scripts/items/cluster_of_fleeting_memories.lua",["SHA256"]="c1ad1c37311850b18b10846071d5e8f2ef8e0eb0a6182a13f9712caea326cefc",["Text"]="-----------------------------------\n-- ID: 5288\n-- Cluster of fleeting memories\n-- Turn into a stack of fleeting memories\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.FLEETING_MEMORY, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/cluster_of_malevolent_memories.lua"]={["Path"]="scripts/items/cluster_of_malevolent_memories.lua",["SHA256"]="c3363caab139d06b05920f9ca64e9aa87bab536e1ff1dde4865616044134559c",["Text"]="-----------------------------------\n-- ID: 5293\n-- Cluster of malevolent memories\n-- Turn into a stack of malevolent memories\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.MALEVOLENT_MEMORY, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/cluster_of_paprika.lua"]={["Path"]="scripts/items/cluster_of_paprika.lua",["SHA256"]="cd30da929be75fcb0d220a231be74137bc774dcff90eb1909adcd239c9ed62c6",["Text"]="-----------------------------------\n-- ID: 5740\n-- Item: Cluster of Paprika\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility 1\n-- Vitality -3\n-- Defense -1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.VIT, -3)\n    effect:addMod(xi.mod.DEF, -1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cluster_of_profane_memories.lua"]={["Path"]="scripts/items/cluster_of_profane_memories.lua",["SHA256"]="5043002ae5c65663289e41dde8da5c4425e23645cfc0977dade1922a21e2ff80",["Text"]="-----------------------------------\n-- ID: 5289\n-- Cluster of profane memories\n-- Turn into a stack of profane memories\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.PROFANE_MEMORY, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/cluster_of_radiant_memories.lua"]={["Path"]="scripts/items/cluster_of_radiant_memories.lua",["SHA256"]="fda81f3580751e091997547c3d46178fee4dec6351f83f6702be4fa7cb9db118",["Text"]="-----------------------------------\n-- ID: 5292\n-- Cluster of radiant memories\n-- Turn into a stack of radiant memories\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.RADIANT_MEMORY, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/cluster_of_somber_memories.lua"]={["Path"]="scripts/items/cluster_of_somber_memories.lua",["SHA256"]="816cf7fd3dc0e6b7818cc93c76c9ec61d226fc6235d5b8bd2146391bebc0e7bb",["Text"]="-----------------------------------\n-- ID: 5291\n-- Cluster of somber memories\n-- Turn into a stack of somber memories\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.SOMBER_MEMORY, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/cluster_of_startling_memories.lua"]={["Path"]="scripts/items/cluster_of_startling_memories.lua",["SHA256"]="be4db1ec7517f5e591b86e79d7fdd46d611d5155ddaf753e3a8046b4d738d038",["Text"]="-----------------------------------\n-- ID: 5290\n-- Cluster of startling memories\n-- Turn into a stack of startling memories\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.STARTLING_MEMORY, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/coated_shield.lua"]={["Path"]="scripts/items/coated_shield.lua",["SHA256"]="c1ed8846f9f2bce6279c56caf7a0532c37b7075b813bbb36009abe6695d2ae81",["Text"]="-----------------------------------\n-- ID: 12406\n-- Item: Coated Shield\n-- Item Effect: Shell\n-- Duration : 3 Minutes\n-- Stacks with Shell (Spell)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.COATED_SHIELD) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.COATED_SHIELD)\n        if effect then\n            effect:resetStartTime()\n            effect:setIcon(xi.effect.SHELL)\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 180, icon = xi.effect.SHELL, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.COATED_SHIELD, flag = xi.effectFlag.NO_LOSS_MESSAGE })\n        end\n\n        target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.SHELL)\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DMGMAGIC, -1055) -- Equivalent to Shell I\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.COATED_SHIELD)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    target:messageBasic(xi.msg.basic.STATUS_WEARS_OFF, xi.effect.SHELL)\nend\n\nreturn itemObject\n"},["scripts/items/cobalt_jellyfish.lua"]={["Path"]="scripts/items/cobalt_jellyfish.lua",["SHA256"]="45597a71f86567fa7b601eaac5aea038ea2e2cb84576c2dbdc72c3512797cae4",["Text"]="-----------------------------------\n-- ID: 4443\n-- Item: cobalt_jellyfish\n-- Food Effect: 5 Min, Mithra only\n-----------------------------------\n-- Dexterity 1\n-- Mind -3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 1)\n    effect:addMod(xi.mod.MND, -3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cobra_staff.lua"]={["Path"]="scripts/items/cobra_staff.lua",["SHA256"]="c942f8a2af17715e59eb9b92da23f7669784f2f6560685a08581e18828dc3991",["Text"]="-----------------------------------\n-- ID: 18614\n-- Cobra Staff\n-- Enchantment: \"Retrace\" (Windurst Waters[S])\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.WINDURST_WATERS_S, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/coconut_rusk.lua"]={["Path"]="scripts/items/coconut_rusk.lua",["SHA256"]="aa6acda4b70cda8cd2b89ca6fd8bcb9ac9fd129b23fc16214a0081959daea5e4",["Text"]="-----------------------------------\n-- ID: 5784\n-- Item: coconut_rusk\n-- Food Effect: 30 Min, All Races\n-----------------------------------\n-- High-quality success rate +3\n-- Synthesis failure rate -6%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.SYNTH_HQ_RATE, 3)\n    effect:addMod(xi.mod.SYNTH_MATERIAL_LOSS, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/coeurl_sub.lua"]={["Path"]="scripts/items/coeurl_sub.lua",["SHA256"]="356cc65250f7f7b29a0222ce5dfd2c1bd7ce34c34f67c7b6dcd86b4e789a279b",["Text"]="-----------------------------------\n-- ID: 5166\n-- Item: coeurl_sub\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Magic 10\n-- Strength 5\n-- Agility 1\n-- Intelligence -2\n-- Health Regen While Healing 1\n-- Attack % 20\n-- Attack Cap 75\n-- Ranged ATT % 20\n-- Ranged ATT Cap 75\n-- Resist Stun +4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 10)\n    effect:addMod(xi.mod.STR, 5)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.INT, -2)\n    effect:addMod(xi.mod.HPHEAL, 1)\n    effect:addMod(xi.mod.FOOD_ATTP, 20)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 75)\n    effect:addMod(xi.mod.FOOD_RATTP, 20)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 75)\n    effect:addMod(xi.mod.STUNRES, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/coeurl_sub_+1.lua"]={["Path"]="scripts/items/coeurl_sub_+1.lua",["SHA256"]="97085d7a76c655444c3cd7e0992c358e946e3c98bcfff4df98e2f5d32a194b34",["Text"]="-----------------------------------\n-- ID: 5167\n-- Item: coeurl_sub_+1\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Magic 15\n-- Strength 5\n-- Agility 1\n-- Intelligence -2\n-- Health Regen While Healing 1\n-- Attack % 22\n-- Attack Cap 80\n-- Ranged ATT % 22\n-- Ranged ATT Cap 80\n-- Sleep Resist 1\n-- Stun Resist 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 15)\n    effect:addMod(xi.mod.STR, 5)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.INT, -2)\n    effect:addMod(xi.mod.HPHEAL, 1)\n    effect:addMod(xi.mod.FOOD_ATTP, 22)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 80)\n    effect:addMod(xi.mod.FOOD_RATTP, 22)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 80)\n    effect:addMod(xi.mod.SLEEPRES, 1)\n    effect:addMod(xi.mod.STUNRES, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/coffee_macaron.lua"]={["Path"]="scripts/items/coffee_macaron.lua",["SHA256"]="72a4c116c840bce66c1d64cf9ee83af76e45b72e7abaa59ca9a3bc70662fa7f4",["Text"]="-----------------------------------\n-- ID: 5780\n-- Item: coffee_macaron\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Increases rate of synthesis success +5%\n-- Increases synthesis skill gain rate +5%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.SYNTH_SUCCESS_RATE, 5)\n    effect:addMod(xi.mod.SYNTH_SKILL_GAIN, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/coffeecake_muffin.lua"]={["Path"]="scripts/items/coffeecake_muffin.lua",["SHA256"]="c4f6e08aacd9e423aca832fe9fb7f90f975c0213d45c8bb0020af5edaec6e009",["Text"]="-----------------------------------\n-- ID: 5655\n-- Item: coffeecake_muffin\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Mind 1\n-- Strength -1\n-- MP % 10 (cap 85)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MND, 1)\n    effect:addMod(xi.mod.STR, -1)\n    effect:addMod(xi.mod.FOOD_MPP, 10)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 85)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/coffeecake_muffin_+1.lua"]={["Path"]="scripts/items/coffeecake_muffin_+1.lua",["SHA256"]="d26a183e55acfbb41dff9b81cfeba25ca0c8bc567f6c266f792f0b32c6045f28",["Text"]="-----------------------------------\n-- ID: 5656\n-- Item: coffeecake_muffin_+1\n-- Food Effect: 1Hr, All Races\n-----------------------------------\n-- Mind 2\n-- Strength -1\n-- MP % 10 (cap 90)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MND, 2)\n    effect:addMod(xi.mod.STR, -1)\n    effect:addMod(xi.mod.FOOD_MPP, 10)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 90)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/coin_cookie.lua"]={["Path"]="scripts/items/coin_cookie.lua",["SHA256"]="3609e3709a9314c428b946c8d6a172cbe8b533f61b5a0fd1f2cb6752982afd49",["Text"]="-----------------------------------\n-- ID: 4520\n-- Item: coin_cookie\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Magic Regen While Healing 6\n-- Vermin Killer 12\n-- Poison Resist 12\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MPHEAL, 6)\n    effect:addMod(xi.mod.VERMIN_KILLER, 12)\n    effect:addMod(xi.mod.POISONRES, 12)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/colichemarde.lua"]={["Path"]="scripts/items/colichemarde.lua",["SHA256"]="ce0aa0c5e5ad752dde10ca0279dacd1bfca9ba685f00ca20b699182e72f45e92",["Text"]="-----------------------------------\n-- ID: 16515\n-- Item: Colichemarde\n-- Additional effect: darkness damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local power  = 4 + utils.clamp(dStat * 35 / 54, 0, 35) -- Linear interp\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(power, power + 7),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.DARK,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/colichemarde_+1.lua"]={["Path"]="scripts/items/colichemarde_+1.lua",["SHA256"]="0cda96647a6c927f4d6b84164dd5da57ba972eab7f4a1ae6914b88ee67a80cca",["Text"]="-----------------------------------\n-- ID: 17632\n-- Item: Colichemarde +1\n-- Additional effect: darkness damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local power  = 4 + utils.clamp(dStat * 35 / 54, 0, 35) -- Linear interp\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(power, power + 7),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.DARK,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/colored_egg.lua"]={["Path"]="scripts/items/colored_egg.lua",["SHA256"]="8c2b41ce31a8a59b23026a55f4b1a561c933a2e395e64dc5f0ed5dcc98058f33",["Text"]="-----------------------------------\n-- ID: 4487\n-- Item: colored_egg\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health 20\n-- Magic 20\n-- Attack 3\n-- Ranged Attack 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 20)\n    effect:addMod(xi.mod.FOOD_MP, 20)\n    effect:addMod(xi.mod.ATT, 3)\n    effect:addMod(xi.mod.RATT, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/combat_casters_quiver.lua"]={["Path"]="scripts/items/combat_casters_quiver.lua",["SHA256"]="46f98a2105eb10d339c08b038224823d28dfa9b98a6d68b10eb6622688069609",["Text"]="-----------------------------------\n-- ID: 15958\n-- Combat Caster's Quiver\n-- When used, you will obtain one Combat Caster's Arrow\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.COMBAT_CASTERS_ARROW, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/companions_die.lua"]={["Path"]="scripts/items/companions_die.lua",["SHA256"]="87274e0d722ae3b049154fd6a3de811732c540b40af2879dec0b68e4bf97f379",["Text"]="-----------------------------------\n-- ID: 5504\n-- Companions Die\n-- Teaches the job ability Companions Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.COMPANIONS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.COMPANIONS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/cone_calamary.lua"]={["Path"]="scripts/items/cone_calamary.lua",["SHA256"]="65a2caf7251517e44faaf3938669629edefd118a679c0f2cbd46e2114d4fce68",["Text"]="-----------------------------------\n-- ID: 5128\n-- Item: Cone Calamary\n-- Food Effect: 5Min, Mithra only\n--------