   effect:addMod(xi.mod.FOOD_RATT_CAP, 40)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cone_of_seraphs_kiss.lua"]={["Path"]="scripts/items/cone_of_seraphs_kiss.lua",["SHA256"]="b65fa87541d1432c8cdd46f2390ac4b44b873b8f980bd6a3227f685b1841db81",["Text"]="-----------------------------------\n-- ID: 5556\n-- Item: cone_of_seraphs_kiss\n-- Food Effect: 1Hr, All Races\n-----------------------------------\n-- HP 15\n-- MP % 16 (cap 85)\n-- MP Recovered While Healing 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 15)\n    effect:addMod(xi.mod.FOOD_MPP, 16)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 85)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cone_of_snoll_gelato.lua"]={["Path"]="scripts/items/cone_of_snoll_gelato.lua",["SHA256"]="c0ced0d31f3eca290380a1a316ae4181bbb03c756a9f7b50b61788d65a27541d",["Text"]="-----------------------------------\n-- ID: 5147\n-- Item: cone_of_snoll_gelato\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- MP % 16 (cap 75)\n-- MP Recovered While Healing 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 16)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 75)\n    effect:addMod(xi.mod.MPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/cone_of_sub-zero_gelato.lua"]={["Path"]="scripts/items/cone_of_sub-zero_gelato.lua",["SHA256"]="3635bb238ada509c56bdee165a154fbd4f463862d5afbef55f5c2bfb84ce98b9",["Text"]="-----------------------------------\n-- ID: 5155\n-- Item: cone_of_sub-zero_gelato\n-- Food Effect: 1Hr, All Races\n-----------------------------------\n-- HP 10\n-- MP % 16 (cap 80)\n-- MP Recovered While Healing 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.FOOD_MPP, 16)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 80)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/congestus_cell.lua"]={["Path"]="scripts/items/congestus_cell.lua",["SHA256"]="9878ab587f7a07ccadb9b2135b3b11b7dcdb8410264d0be5a61d1f3b685c57c9",["Text"]="-----------------------------------\n-- Congestus Cell\n-- ID 5378\n-- Removes VIT Down effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.salvage.onCellItemCheck(target, xi.effect.DEBILITATION, 0x004)\nend\n\nitemObject.onItemUse = function(target)\n    return xi.salvage.onCellItemUse(target, xi.effect.DEBILITATION, 0x004, 13)\nend\n\nreturn itemObject\n"},["scripts/items/container_of_carnal_incense.lua"]={["Path"]="scripts/items/container_of_carnal_incense.lua",["SHA256"]="dffcac01bfd5073c2cdcdb355d688b2ef10836d61c82346c2f3a61681ff47237",["Text"]="-----------------------------------\n-- ID: 5243\n-- Item: container_of_carnal_incense\n-- Item Effect: When applied, grants UDMGPHYS -10000 for 20s\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect        = xi.effect.PHYSICAL_SHIELD\n    local duration      = 20\n    local power         = 1\n    local mitigatews    = 2\n\n    xi.itemUtils.addItemShield(target, power, duration, effect, mitigatews)\nend\n\nreturn itemObject\n"},["scripts/items/container_of_spiritual_incense.lua"]={["Path"]="scripts/items/container_of_spiritual_incense.lua",["SHA256"]="4c5801fa7972db5c7966d4418c52b9dc53584b0d87ac5e99eb3a29b5017b4d20",["Text"]="-----------------------------------\n-- ID: 5244\n-- Item: container_of_spiritual_incense\n-- Item Effect: When applied, grants UDMGMAGIC -10000 for 20s\n--              Does not Grant Spell Immunity (nospellimmune = 1)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect        = xi.effect.MAGIC_SHIELD\n    local duration      = 20\n    local power         = 1\n    local nospellimmune = 1\n\n    xi.itemUtils.addItemShield(target, power, duration, effect, nospellimmune)\nend\n\nreturn itemObject\n"},["scripts/items/copper_frog.lua"]={["Path"]="scripts/items/copper_frog.lua",["SHA256"]="919a641f9a283e6a192e42e228f904c0de19c56859afe64a1a8474cc7eb3a511",["Text"]="-----------------------------------\n-- ID: 4515\n-- Item: copper_frog\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Agility 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.AGI, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_aid_for_all.lua"]={["Path"]="scripts/items/copy_of_aid_for_all.lua",["SHA256"]="2769d9a2457a9295c5166d06f9d1d2897f1f1bf16a6623f93fc90b43ebca46f2",["Text"]="-----------------------------------\n-- ID: 6168\n-- Item: Aid for All\n-- A guide to the finer points of heightening the potential of one's compatriots, written by Rainemard.\n-- It also includes some tips on how to swing special swords.\n-- Adventurers note that reading it increases one's enhancing magic skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.ENHANCING_MAGIC)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.ENHANCING_MAGIC)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_altanas_hymn.lua"]={["Path"]="scripts/items/copy_of_altanas_hymn.lua",["SHA256"]="5ba9bc9a48e692813a9666de0920e1c8a5eee61fe67cbacc57cc9ca45a6bd6a4",["Text"]="-----------------------------------\n-- ID: 6166\n-- Item: Altana's Hymn\n-- A copy of Febrenard C Brunnaut's favorite read.\n-- The simple lyrics and enchanting meter were said to have soothed his soul.\n-- Adventurers note that reading it increases one's divine magic skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.DIVINE_MAGIC)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.DIVINE_MAGIC)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_astral_homeland.lua"]={["Path"]="scripts/items/copy_of_astral_homeland.lua",["SHA256"]="cde7dac8ffa19d8809a964c035f0fe259b430ffe99e256a81c478dac38b68728",["Text"]="-----------------------------------\n-- ID: 6176\n-- Item: Astral Homeland\n-- A specious work written by an unknown individual that both reads and feels like an illusion from the ancient past.\n-- It discusses the world avatars inhabit, but seems too absurd to be true.\n-- Adventurers note that reading it increases one's summoning magic skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.SUMMONING_MAGIC)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.SUMMONING_MAGIC)\nend\n\nreturn itemObject\n"},["scripts/items/copy_of_barrels_of_fun.lua"]={["Path"]="scripts/items/copy_of_barrels_of_fun.lua",["SHA256"]="32d87bf94e8d764ba7b23af82ced0b502dc84410eeb40840bb785d592e08cfdd",["Text"]="-----------------------------------\n-- ID: 6160\n-- Item: Barrels of Fun\n-- An educational text authored by Elivira Gogol.\n-- It discusses how to dismantle, clean, and reconstruct firearms in careful detail.\n-- Adventurers note that reading it increases one's marksmanship skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.MARKSMANSHIP)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.MARKSMANSHIP)\nend\n\nreturn itemObject\n"}};
